<?php
namespace App\Controllers;use App\Core\Database;use App\Core\Security;
final class ReportController{public function index():void{$rows=Database::connection()->query('SELECT c.*,b.title FROM checkouts c JOIN books b ON b.id=c.book_id ORDER BY c.checked_out_at DESC')->fetchAll();$title='Reports';require BASE_PATH.'/app/Views/reports/index.php';}private function rows():array{return Database::connection()->query('SELECT b.title,c.borrower_name,c.borrower_id,c.checked_out_at,c.due_date,c.returned_at,c.status,c.fine FROM checkouts c JOIN books b ON b.id=c.book_id ORDER BY c.checked_out_at DESC')->fetchAll();}public function csv():never{$rows=$this->rows();header('Content-Type:text/csv');header('Content-Disposition:attachment;filename=library-inventory-report.csv');$o=fopen('php://output','w');fputcsv($o,['Book','Borrower','ID','Checked out','Due date','Returned','Status','Fine']);foreach($rows as $r)fputcsv($o,$r);exit;}public function pdf():never{$rows=$this->rows();$html='<html><head><style>body{font-family:Arial;font-size:11px}h1{color:#333}table{width:100%;border-collapse:collapse}th,td{border:1px solid #bbb;padding:6px;text-align:left}th{background:#20252b;color:#fff}</style></head><body><h1>Library Inventory Circulation Report</h1><p>Generated '.date('Y-m-d H:i').'</p><table><tr><th>Book</th><th>Borrower</th><th>ID</th><th>Checked out</th><th>Due</th><th>Returned</th><th>Status</th><th>Fine</th></tr>';foreach($rows as $r){$html.='<tr>';foreach($r as $v)$html.='<td>'.htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8').'</td>';$html.='</tr>';}$html.='</table></body></html>';if(is_file(BASE_PATH.'/vendor/autoload.php')){require_once BASE_PATH.'/vendor/autoload.php';$dompdf=new \Dompdf\Dompdf();$dompdf->loadHtml($html);$dompdf->setPaper('A4','landscape');$dompdf->render();$dompdf->stream('library-inventory-report.pdf',['Attachment'=>true]);exit;}header('Content-Type:text/html; charset=utf-8');echo $html.'<script>window.print()</script>';exit;}}
